// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1e30);
        vm.warp(1_000_000);
        unlockTime = bound(unlockTime, 1_000_001, type(uint256).max / 2);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // Rule: after a deposit with a future unlock time, the stored unlock time
        // (field 0 of Acc[actor]) must be exactly the caller-supplied future time.
        assertTrue(c.Acc(actor, 0) == unlockTime);
    }
}

