pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 warpTo, uint256 unlockTime, uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        warpTo = bound(warpTo, 1, 1e12);
        unlockTime = bound(unlockTime, warpTo + 1, warpTo + 1e12);
        amount = bound(amount, 1, 100 ether);
        vm.warp(warpTo);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        // General rule: stored unlockTime is the LATER of _unlockTime and block.timestamp,
        // so for any future _unlockTime it must equal _unlockTime exactly.
        assertTrue(c.Acc(actor).unlockTime == unlockTime);
    }
}

