pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 warpTo, address actor, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        vm.assume(unlockTime > type(uint256).max - 1 ether ? false : true);
        unlockTime = bound(unlockTime, block.timestamp + 1, type(uint256).max - 1);
        warpTo = bound(warpTo, block.timestamp, block.timestamp + 1 days);
        vm.warp(warpTo);

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.Put{value: 0}(unlockTime);

        (, uint256 stored) = c.Acc(actor);
        assertTrue(stored == unlockTime);
    }
}

