pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint constant NOW = 1000;

    function setUp() public { c = new C(address(new Log())); vm.warp(NOW); }

    function testFuzz_property(uint256 unlockTime, address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(unlockTime > NOW); // admissible: user may lock into the future
        amount = bound(amount, 0, 1 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        assertTrue(c.Acc(actor).unlockTime >= unlockTime);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 ts, uint256 t, address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 10 ether);
        uint256 ts0 = bound(ts, 1, 2) * 1 days + 1;
        uint256 t = bound(t, 1, 365 days);
        vm.deal(actor, amount);

        vm.warp(ts0);
        vm.prank(actor);
        c.Put{value: amount}(0);
        // now unlockTime == ts0
        vm.warp(ts0 + 10 days);
        vm.prank(actor);
        c.Put{value: amount}(ts0 + t);

        assertTrue(c.Acc(actor).unlockTime >= ts0 + t);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {}
    function test(uint dep, uint amt) public {
        require(dep >= 2 ether);
        require(amt >= 1 ether && amt <= dep);
        require(address(this).balance >= dep);
        c.Put{value: dep}(0);
        c.Collect(amt);
        (, uint bal) = c.Acc(address(this));
        assert(bal == dep - amt);
    }
}
